export interface OrderLine {
  slug: string
  name: string
  qty: number
}

/** Order as returned by `GET /api/orders/:id`. Amounts use the server format, e.g. `19.99 USD`. */
export interface Order {
  id: string
  lines: OrderLine[]
  subtotal: string
  discount: string
  total: string
}

import type { CartLine } from '#shared/types/cart'
import type { Order, OrderLine } from '#shared/types/order'
import { randomUUID } from 'node:crypto'
import { findProduct } from '#server/utils/db'
import { computeQuote } from '#server/utils/quote'

/** Orders live in server memory only; they are lost when the server restarts. */
const orders = new Map<string, Order>()

/** Stores an order for the given lines. Amounts come from `computeQuote`, so they match the quote API. */
export function createOrder(lines: CartLine[], code?: string): Order {
  const quote = computeQuote(lines, code)
  const orderLines: OrderLine[] = lines.map(line => ({
    slug: line.slug,
    name: findProduct(line.slug)?.name ?? line.slug,
    qty: line.qty,
  }))
  const order: Order = { id: randomUUID(), lines: orderLines, ...quote }
  orders.set(order.id, order)
  return order
}

export function findOrder(id: string): Order | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'
import { createError, defineEventHandler, readBody } from 'h3'
import { createOrder } from '#server/utils/orders'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: string }>(event)
  if (!Array.isArray(body?.lines))
    throw createError({ statusCode: 400, statusMessage: '`lines` must be an array' })
  const { id, subtotal, discount, total } = createOrder(body.lines, body.code)
  return { id, subtotal, discount, total }
})

